// historicalWorkflowDefinitions decodes the retained version-1 manifests. The
// digests are asserted at registration time by the golden test; a manifest that
// fails to decode or validate panics during registry init, which is a
// programmer error rather than a runtime condition.
func historicalWorkflowDefinitions() []WorkflowDefinition {
	definitions := make([]WorkflowDefinition, 0, len(historicalWorkflowManifests))
	for _, historical := range historicalWorkflowManifests {
		var definition WorkflowDefinition
		if err := json.Unmarshal([]byte(historical.manifest), &definition); err != nil {
			panic(err)
		}
		definitions = append(definitions, definition)
	}
	return definitions
}
